def mru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = dict()
        stats = {'hits': 0, 'misses': 0}

        def memoized(*args):
            if not typed and len(args) == 1 and isinstance(args[0], tuple):
                args = args[0]
            key = args
            try:
                if key in cache:
                    stats['hits'] += 1
                    return cache[key]
                else:
                    stats['misses'] += 1
                    value = func(*args)
                    cache[key] = value
                    return value
            except KeyError:
                pass
            except TypeError:
                pass

        memoized.cache = cache
        memoized.stats = stats
        memoized.reset = lambda: cache.clear()
        return memoized

    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def memoize(func):
        cache = {}
        @functools.wraps(func)
        def _memoized_func(*args, **kwargs):
            key = (args, tuple(sorted(kwargs.items())))
            if key not in cache or (typed and type(cache[key]) is not type(func(*args, **kwargs))):
                cache[key] = func(*args, **kwargs)
            return cache[key]
        return _memoized_func
    return memoize

