def extostr(cls, e, max_level=30, max_path_level=5):
    msg = ""
    lvl = 0
    while lvl < max_level:
        if not hasattr(e, "__traceback__") or lvl == max_level:
            msg += f" - {type(e).__name__}: {str(e)}"
            break
        else:
            msg += f" - {type(e).__name__}: {str(e)}"
            e = e.__cause__
        lvl += 1
        if lvl == max_path_level:
            msg += "..."
    return msg

