def minimalBases(classes) -> List[Type]:
    bases = set(classes)
    result = []
    while bases:
        base = bases.pop()
        for other in bases:
            if other in base.__mro__:
                bases.remove(other)
                continue
            else:
                for base in base.__mro__:
                    if base in other.__mro__:
                        bases.remove(other)
                        continue
        result.append(base)
    return result

