    if not isinstance(sequence, collections.abc.Sequence):
        raise TypeError("The input must be a sequence")
    # Check if the output is a sequence
    if output is not None and not isinstance(output, collections.abc.Sequence):
        raise TypeError("The output must be a sequence")
    # Normalize the arguments
    normalized_args = []
    for arg in sequence:
        # If the argument is a direct type, add it to the list
        if isinstance(arg, type):
            normalized_args.append(arg)
            continue
        # If the argument is a tuple, normalize the tuples
