    # Check if required keys are present in the inventory
    if "name" not in inventory or "type" not in inventory:
        raise ValueError("Invalid inventory: inventory must contain 'name' and 'type' keys")
    # Check if type is valid
    if "type" in inventory and inventory["type"] not in ["hardware", "software"]:
        raise ValueError("Invalid inventory: inventory type must be either 'hardware' or 'software'")
    # Check if no conflict exists between type and spec_version values
    if "spec_version" in inventory and extract_spec_version:
        if inventory["type"] == "hardware":
            raise ValueError("Invalid inventory: hardware inventory cannot have 'spec_version' attribute")
        elif inventory["type"] == "software":
            if not isinstance(inventory["spec_version"], str):
                raise ValueError("Invalid inventory: 'spec_version' must be a string type")
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    all_digests = set()
    used_digests = set()
    for manifest_file in manifest_files:
        digests = manifest_file.get_digests()
        all_digests.update(digests)
        used_digests.update(digests_used)

    if all_digests != used_digests:
        raise ValueError(f"Missing or unused digest(s): {all_digests - used_digests}")

    return True

