import dateutil.relativedelta

class relativedelta:
    def __init__(self, *args, **kwargs):
        self.args = args
        self.kwargs = kwargs

    def normalized(self):
        output = relativedelta()
        for arg in self.args:
            if isinstance(arg, relativedelta):
                output += arg.normalized()
            else:
                output += relativedelta(arg)
        for kwarg in self.kwargs:
