def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        if sys.platform.startswith(('win', 'darwin')):
            # Windows or macOS
            regex = r'([^\s"\'\\]+|"[^"\\]+"|\'[^\'\\]+\')(?:\s+|$)'
        else:
            # POSIX (Linux, etc.)
            regex = r'([^\s"+]+|"[^"\\]+"|\'[^\'\\]+\')(?:\s+|$)'
    elif platform == 1:
        # POSIX
        regex = r'([^\s"+]+|"[^"\\]+"|\'[^\'\\]+\')(?:\s+|$)'
    elif platform == 0:
        # Windows/CMD
        regex = r'([^\s"\'\\]+|"[^"\\]+"|\'[^\'\\]+\')(?:\s+|$)'
    else:
        return []
    return re.split(regex, s)

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    if not os.path.isfile(archive_path):
        raise ValueError("Archive file does not exist")

    if filename is None:
        filename = os.path.basename(archive_path)

    tmp_path = os.path.abspath(tmp_path)
    if not os.path.isdir(tmp_path):
        raise ValueError("Temporary directory does not exist")

    archive = os.path.join(tmp_path, f"{filename}.tar.gz")
    if os.path.exists(archive):
        shutil.move(archive, os.path.join(tmp_path, f"backup-{filename}.tar.gz"))

    shutil.unpack_archive(archive_path, tmp_path)
    repo_url = os.path.join(tmp_path, filename)

    return repo_url

