def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if not tentative:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid("Candidate does not implement the interface")
        for name, method in inspect.getmembers(candidate, inspect.isfunction):
            req = iface.getMethod(name)
            if not req:
                raise zope.interface.Invalid("Candidate does not define required method {}".format(name))
            if not signature_match(req, method):
                raise zope.interface.Invalid("Candidate method {} signature does not match".format(name))
        for name, attribute in inspect.getmembers(candidate, lambda t: not inspect.isfunction(t)):
            req = iface.getAttribute(name)
            if not req:
                raise zope.interface.Invalid("Candidate does not define required attribute {}".format(name))
            if not signature_match(req, attribute):
                raise zope.interface.Invalid("Candidate attribute {} signature does not match".format(name))
        return True
    except Exception as e:
        raise zope.interface.Invalid(e)

def verifyObject(iface, candidate, tentative=False):
    if not isinstance(candidate, type):
        raise ValueError("Invalid `candidate`: expected a class")
    if not isinstance(iface, type):
        raise ValueError("Invalid `iface`: expected a class")

    try:
        if not tentative:
            assert iface.providedBy(candidate)
        defined_methods = {
            m for m in candidate.__dict__.values()
            if isinstance(m, types.MethodType)
        }
        required_method_names = {
            n for n, p in iface.namesAndSignatures()
            if p == "method"
        }
        for method_name in required_method_names:
            if method_name not in defined_methods:
                raise ValueError(
                        f"Method {method_name} not defined on {candidate}"
                )
        for method in defined_methods.values():
            # Check if the method has the correct signature
            # TODO: check signature

        defined_attrs = {
            a for a in candidate.__dict__.values()
            if not a.startswith("_")
        }
        required_attr_names = {
            n for n, p in iface.namesAndSignatures()
            if p == "attr"
        }
        for attr_name in required_attr_names:
            if attr_name not in defined_attrs:
                raise ValueError(
                        f"Attribute {attr_name} not defined on {candidate}"
                )

        return True
    except Exception as e:
        raise zope.interface.Invalid(str(e))

