def parse(timestr, default=None, ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("timestr must be a string")

    # Convert the default datetime object to a datetime.datetime and timezone object
    default_date = None
    default_tz = None
    if default is not None:
        if isinstance(default, datetime.datetime):
            default_date = default
        elif isinstance(default, datetime.tzinfo):
            default_tz = default
        else:
            raise TypeError("default must be a datetime.datetime or datetime.tzinfo object")

    # If ignoretz is True, convert the timestr to a naive datetime.datetime object
    if ignoretz:
        date = datetime.datetime.strptime(timestr, "%Y-%m-%d %H:%M:%S")
    else:
        # Convert the timestr to a datetime.datetime object with the appropriate timezone
        if tzinfos is None:
            date = parse_naive(timestr)
        else:
            date = parse_aware(timestr, tzinfos)

    # If a default datetime object was provided, modify the date with the information from the default
    if default_date is not None:
        date = date.replace(year=default_date.year, month=default_date.month, day=default_date.day,
                           hour=default_date.hour, minute=default_date.minute, second=default_date.second,
                           microsecond=default_date.microsecond)

    # If a default timezone was provided, set the timezone of the date to the default timezone
    if default_tz is not None:
        date = date.astimezone(default_tz)

    return date

def fromutc(self, dt):
    try:
        if not isinstance(dt, datetime.datetime):
            raise ValueError("dt must be a datetime.datetime object")
        if not dt.tzinfo:
            raise ValueError("dt must be a timezone-aware datetime object")
        # get the current timezone for the input datetime
        local_tz = datetime.datetime.now(dt.tzinfo).tzinfo
        # determine whether the input datetime is ambiguous
        is_ambiguous = local_tz._is_in_dst(dt.replace(tzinfo=None))
        if is_ambiguous:
            # if it's ambiguous, find the local midnight in the next day
            local_midnight = local_tz._get_next_dst(dt.replace(tzinfo=None))
            # and return that time in the input datetime's timezone
            return local_midnight.astimezone(dt.tzinfo)
        else:
            # otherwise, simply return the input datetime as-is
            return dt
    except Exception as e:
        raise ValueError("Input must be a valid datetime object") from e

