            defaults[param.name] = param.default_factory()
        # Check if parameter has a type
        elif param.type is not None:
            defaults[param.name] = argparse.namespace(param.type)
        # Check if parameter has an annotation
        elif param.annotation is not None:
            defaults[param.name] = param.annotation
        # If all else fails, set default value to None
