                values_dict_copy[arg] = values_dict_copy[arg][1:-1].split(",")
            else:
                # Try to cast to int
                try:
                    values_dict_copy[arg] = int(values_dict_copy[arg])
                except ValueError:
                    # Try to cast to float
                    try:
                        values_dict_copy[arg] = float(values_dict_copy[arg])
                    except ValueError as e:
                        # Check if the argument is a bool
                        if values_dict_copy[arg].lower() == "true":
                            values_dict_copy[arg] = True
                        elif values_dict_copy[arg].lower() == "false":
                            values_dict_copy[arg] = False
                        else:
                            # Set the argument to its original value
                            values_dict_copy[arg] = values_dict_copy[arg]
    return values_dict_copy

def get_plugin_spec_flatten_dict(plugin_dir):
    try:
        with open(f"{plugin_dir}/plugin.json") as data_file:
            data = json.load(data_file)
            flattened_data = {}
            for key, value in data.items():
                if isinstance(value, dict):
                    for sub_key, sub_value in value.items():
                        flattened_data[f"{key}.{sub_key}"] = sub_value
                else:
                    flattened_data[key] = value
            return flattened_data
    except Exception as e:
        print("Exception while reading plugin.json:", e)
        return {}

def inject_config(self: 'Injector'):
  """Set the environment variable for config path, if it is undefined."""
  if os.environ.get("CONFIG_PATH") is None:
    os.environ["CONFIG_PATH"] = os.path.join(
      os.path.dirname(os.path.abspath(__file__)), "config.yaml"
    )

def strip_root(path, root):
    if not path.startswith(root):
        raise ValueError("Root not found in path")
    return path[len(root):]
